-- =====================================================================
--  FARMA - 480 productos adicionales (FAR-0021 a FAR-0500)
--  Junto con los 20 de farma_db_completo.sql quedan 500 productos.
--
--  CÓMO USARLO EN MySQL Workbench:
--    1. Primero ejecuta farma_db_completo.sql (o ten ya creada farma_db).
--    2. Abre este archivo y ejecútalo completo con el rayo.
--    3. Al final debe mostrar total_productos = 500.
--
--  Se puede volver a ejecutar sin problema: INSERT IGNORE salta los códigos
--  que ya existen. Los productos sin foto propia muestran la imagen genérica.
-- =====================================================================
SET NAMES utf8mb4;
USE `farma_db`;


SELECT COUNT(*) AS total_productos FROM productos;
SELECT categoria, COUNT(*) AS productos FROM productos GROUP BY categoria ORDER BY productos DESC;
